def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c] != 0]

    # The colored marks lie on parallel diagonals. Choose their orientation
    # by finding which diagonal coordinate has fewer distinct values.
    keys = [
        [c - r for r, c, _ in cells],
        [r + c for r, c, _ in cells],
    ]
    axis = min(range(2), key=lambda i: len(set(keys[i])))
    period = len(set(keys[axis]))

    colors = {}
    for (r, c, color), key in zip(cells, keys[axis]):
        colors[key % period] = color

    return [
        [colors[(c - r if axis == 0 else r + c) % period]
         for c in range(w)]
        for r in range(h)
    ]
